define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_2.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e4172","topics":[]},{"title":"Applying LOTO - MDP","shortdesc":"<p class=\"shortdesc\"><span class=\"ph uicontrol\">Note: <\/span>Prior to applying LOTO to the system do the Disk Wipe procedure, which can be found on the documentation library. Search on document 5500610-1. Apply LOTO to the MDP or the facility PDU before removing power to these items. Facility-level LOTO must be done by an electrician.<\/p>","href":"t_Applying-LOTO-MDP-Premier_2.html","attributes":{"data-id":"id_2001934"},"menu":{"hasChildren":false},"tocID":"id_2001934-d46e4276","topics":[]},{"title":"Doing a check of the internal power wiring to the System Power Distribution Unit (SPDU)","shortdesc":"<p class=\"shortdesc\">Do a check of the internal wiring of power to the SPDU.<\/p>","href":"t_ConfirmInternalPowerWiringToSystemPowerDistributionUnitSPDU.html","attributes":{"data-id":"id_2003022"},"menu":{"hasChildren":false},"tocID":"id_2003022-d46e4486","topics":[]},{"title":"Doing a check of the internal power wiring to the Gradient Power Distribution Unit (GPDU)","shortdesc":"<p class=\"shortdesc\">Do a check of the internal wiring of power to the GPDU.<\/p>","href":"t_ConfirmingInternalPowerWiringToGradientPowerDistributionUnit.html","attributes":{"data-id":"id_2002953"},"menu":{"hasChildren":false},"tocID":"id_2002953-d46e4590","topics":[]},{"title":"Doing a check of the overload and short circuit trip settings for the <span class=\"ph\">Gradient Power Distribution Unit (GPDU)<\/span> input circuit breaker","shortdesc":"<p class=\"shortdesc\">Do a check of the <span class=\"ph\">GPDU<\/span> settings for various voltages.<\/p>","href":"t_ConfirmingOverloadAndShortCircuitTripSettingsForPDUInputCircuitBreaker.html","attributes":{"data-id":"id_2001392"},"menu":{"hasChildren":false},"tocID":"id_2001392-d46e4694","topics":[]},{"title":"Doing a check of the gradient cable connection at the gradient filter","shortdesc":"<p class=\"shortdesc\">Do a check of the connection of the gradient cable to the gradient filter.<\/p>","href":"t_CheckingGradientCableConnectionAtGradientFilter.html","attributes":{"data-id":"id_2001393"},"menu":{"hasChildren":false},"tocID":"id_2001393-d46e4804","topics":[]},{"title":"Setting the <span class=\"ph\">Integrated System Cabinet (ISC) System Power Distribution Unit (SPDU)<\/span> breakers and sub breakers","shortdesc":"<p class=\"shortdesc\">Complete these steps to finish the first portion of the power on procedure.<\/p>","href":"t_SettingTheISCSPDUBreakersAndSubBreakers.html","attributes":{"data-id":"id_2003027"},"menu":{"hasChildren":false},"tocID":"id_2003027-d46e4908","topics":[]},{"title":"Completing the power on sequence","shortdesc":"<p class=\"shortdesc\">Do final steps to complete the power on sequencing.<\/p>","href":"t_CompletingThePowerOnSequence.html","attributes":{"data-id":"id_2002884"},"menu":{"hasChildren":false},"tocID":"id_2002884-d46e5121","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_3.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e5226","topics":[]}]});